THOUGHT: I've identified the issue. The problem is in the `daemonManager.Add()` method in `daemon_manager.go`. When the channel is full, the method blocks indefinitely because it's trying to send to a buffered channel that has reached capacity.

The fix is to modify the `Add` method to handle the case when the channel is full. We can either:
1. Increase the buffer size dynamically (not ideal)
2. Use a different synchronization mechanism
3. Process items directly when the buffer is full

I'll implement a solution that processes items in a separate goroutine when the buffer is full to prevent blocking:

```bash
cat <<'EOF' > daemon_manager.go
package main

import (
	"sync"
)

type daemonManager struct {
	daemons   chan func()
	waitGroup *sync.WaitGroup
	mutex     sync.Mutex
	closed    bool
}

func newDaemonManager(capacity int) *daemonManager {
	return &daemonManager{
		daemons:   make(chan func(), capacity),
		waitGroup: &sync.WaitGroup{},
	}
}

func (m *daemonManager) Add(f func()) {
	m.mutex.Lock()
	if m.closed {
		m.mutex.Unlock()
		return
	}
	m.waitGroup.Add(1)
	m.mutex.Unlock()

	// Try to add to the channel, but don't block
	select {
	case m.daemons <- func() {
		f()
		m.waitGroup.Done()
	}:
	default:
		// If channel is full, run the function in a new goroutine directly
		go func() {
			f()
			m.waitGroup.Done()
		}()
	}
}

func (m *daemonManager) Run() {
	// Start a goroutine to process items from the channel
	go func() {
		for f := range m.daemons {
			go f()
		}
	}()

	// Mark as closed to prevent new additions
	m.mutex.Lock()
	m.closed = true
	m.mutex.Unlock()

	// Close the channel to stop the processor goroutine
	close(m.daemons)

	// Wait for all functions to complete
	m.waitGroup.Wait()
}
EOF
```

